type ElementProps<Options, Handle> = Options & {
	/** The element's live handle (same surface as the vanilla `create` return). */
	ref?: Ref<Handle>;
	/** Applied to the element's mount container (the wrapper this component renders; the element itself lives in its own frame, see the Styling docs for restyling it). */
	className?: string;
	/** Applied to the element's mount container (the wrapper this component renders). */
	style?: CSSProperties;
	/** Shown until the element is fully loaded. When omitted, the element's own internal loading UI is shown instead. */
	fallback?: ReactNode;
};

/**
 * Collect a payment from a `plan_` ID or inline currency and amount, or save a payment method without charging with `mode: "setup"`. Mount PaymentElement, CardElement, or CardFields, then call `payments.createConfirmationToken` with billing details. Wallet selections open their sheet automatically. When the account offers in-page bank linking (`bank_debit.bank_connection` on its bank account payment method type), a bank account selection opens Plaid Link on the page too. A buyer who closes either one rejects the call with `payment_request_cancelled`, which your pay handler should treat as a cancel. Confirm the token server-side, then pass the payment's or setup intent's `client_secret` to `handleNextAction` for any pending step.
 * Provider component: creates the PaymentsHandle and drives the element components rendered as children. `fallback` shows until every child element has loaded (grouped); `ref` exposes the live handle. Unmounting it destroys the handle and everything it created.
 * @example
 * ```tsx
 * import { WhopElements, Payments, PaymentElement, AddressElement, CardElement, EmailElement, TaxIdElement, BrandingElement } from "@whop/elements-react";
 * import { loadWhop } from "@whop/elements";
 * 
 * function Example() {
 *   return (
 *     <WhopElements elements={loadWhop()}>
 *       <Payments>
 *         <PaymentElement />
 *         <AddressElement />
 *         <CardElement />
 *         <EmailElement />
 *         <TaxIdElement />
 *         <BrandingElement />
 *       </Payments>
 *     </WhopElements>
 *   );
 * }
 * ```
 * @see https://docs.whop.com/elements/latest/payments/overview
 */
export declare function Payments(
	props: PaymentsOptions & { children?: ReactNode; fallback?: ReactNode; ref?: Ref<{ handle: PaymentsHandle | null }> },
): ReactNode;
/**
 * The nearest `<Payments>` ancestor's live handle, `null` until it boots. Must be called under a `<Payments>`.
 * @see https://docs.whop.com/elements/latest/payments/overview
 */
export declare function usePayments(): PaymentsHandle | null;

/**
 * Shows available payment methods and collects the selected method's required fields and disclosures. Use `change` to enable your pay button. In its activation handler, call `payments.createConfirmationToken()`. Confirm the token server-side, then pass any pending step to `payments.handleNextAction(…)`. Use `addressChange` for address-dependent updates.
 * @example
 * ```tsx
 * import { WhopElements, Payments, PaymentElement } from "@whop/elements-react";
 * import { loadWhop } from "@whop/elements";
 * 
 * function Example() {
 *   return (
 *     <WhopElements elements={loadWhop()}>
 *       <Payments>
 *         <PaymentElement />
 *       </Payments>
 *     </WhopElements>
 *   );
 * }
 * ```
 * @see https://docs.whop.com/elements/latest/payments/payment
 */
export declare function PaymentElement(props: ElementProps<PaymentElementCreateOptions, PaymentElementHandle>): ReactNode;
